// scripts/translators/buildroot-translator.js

const fs = require('fs').promises;
const path = require('path');

/**
 * Translates the ELHLCF JSON config to a Buildroot .config file content.
 * @param {object} config - The parsed elhclf_config.json object.
 * @returns {string} - The content of the Buildroot .config file.
 * @throws {Error} - If required configuration fields are missing or invalid.
 */
function translateToBuildroot(config) {
    const outputLines = [
        '# Buildroot configuration generated by ELHLCF Translator',
        '# Based on elhclf_config.json',
        '# WARNING: This is a best-effort translation. Review and adjust using `make menuconfig`.',
        ''
    ];

    // --- Target ---
    if (!config.target?.architecture) {
        throw new Error("Missing required field: target.architecture");
    }
    // Basic architecture mapping (expand as needed)
    switch (config.target.architecture) {
        case 'armv7':
            outputLines.push('BR2_arm=y');
            outputLines.push('BR2_ARCH="arm"');
            if (config.target.cpu) {
                 // Assuming generic target, adjust if specific boards are supported
                outputLines.push(`BR2_TARGET_GENERIC_ARM_CPU="${config.target.cpu}"`);
            }
            break;
        case 'aarch64':
            outputLines.push('BR2_aarch64=y');
            outputLines.push('BR2_ARCH="aarch64"');
             if (config.target.cpu) {
                outputLines.push(`BR2_TARGET_GENERIC_ARM64_CPU="${config.target.cpu}"`);
            }
           break;
        // Add other architectures (x86_64, riscv, etc.)
        default:
            throw new Error(`Unsupported target architecture: ${config.target.architecture}`);
    }
    outputLines.push('');

    // --- Toolchain ---
    if (!config.toolchain?.type) {
        throw new Error("Missing required field: toolchain.type");
    }
    switch (config.toolchain.type) {
        case 'buildroot':
            outputLines.push('BR2_TOOLCHAIN_BUILDROOT=y');
            // Add specific Buildroot toolchain options if needed (libc, etc.)
            break;
        case 'external':
            outputLines.push('BR2_TOOLCHAIN_EXTERNAL=y');
            if (!config.toolchain.path) {
                throw new Error("Missing required field for external toolchain: toolchain.path");
            }
            outputLines.push(`BR2_TOOLCHAIN_EXTERNAL_PATH="${config.toolchain.path}"`);
            // Add other external toolchain options (prefix, glibc, etc.) based on JSON
            break;
        // Add 'local' type if supported
        default:
            throw new Error(`Unsupported toolchain type: ${config.toolchain.type}`);
    }
    outputLines.push('');

    // --- Kernel ---
    if (config.kernel?.source && config.kernel.source !== 'none') {
        outputLines.push('BR2_LINUX_KERNEL=y');
        if (!config.kernel.defconfig) {
             throw new Error("Missing required field for kernel: kernel.defconfig");
        }
        outputLines.push(`BR2_LINUX_KERNEL_DEFCONFIG="${config.kernel.defconfig}"`);

        switch (config.kernel.source) {
            case 'git':
                if (!config.kernel.gitUrl || !config.kernel.gitRef) throw new Error("Missing gitUrl or gitRef for kernel");
                outputLines.push('BR2_LINUX_KERNEL_CUSTOM_GIT=y');
                outputLines.push(`BR2_LINUX_KERNEL_CUSTOM_REPO_URL="${config.kernel.gitUrl}"`);
                outputLines.push(`BR2_LINUX_KERNEL_CUSTOM_REPO_VERSION="${config.kernel.gitRef}"`);
                break;
            // Add 'tarball', 'local' sources
        }
        // Add kernel options (e.g., modules, DTB) based on JSON
    } else {
        outputLines.push('# BR2_LINUX_KERNEL is not set');
    }
    outputLines.push('');

    // --- Bootloader (Example for U-Boot) ---
    if (config.bootloader?.type === 'uboot') {
        outputLines.push('BR2_TARGET_UBOOT=y');
        if (!config.bootloader.defconfig) throw new Error("Missing defconfig for U-Boot");
        outputLines.push(`BR2_TARGET_UBOOT_BOARD_DEFCONFIG="${config.bootloader.defconfig}"`);
        // Add U-Boot source options (git, tarball, etc.) similar to kernel
    }
    outputLines.push('');

    // --- Filesystem ---
    if (config.filesystem?.type) {
        // Basic mapping (needs refinement based on exact Buildroot options)
        if (config.filesystem.type.startsWith('ext')) { // ext2, ext3, ext4
            outputLines.push('BR2_TARGET_ROOTFS_EXT2=y');
            if (config.filesystem.type === 'ext4') outputLines.push('BR2_TARGET_ROOTFS_EXT2_4=y');
        } // Add other types (squashfs, jffs2, etc.)
    }
    outputLines.push('');

    // --- Packages ---
    if (config.packages && config.packages.length > 0) {
        outputLines.push('# Target packages');
        config.packages.forEach(pkg => {
            // Basic assumption: package name maps directly. Needs refinement for complex packages.
            // Handle potential naming mismatches (e.g., json 'openssh' -> buildroot 'openssh')
            const brPackage = pkg.toUpperCase().replace(/-/g, '_'); // Simple transformation
            outputLines.push(`BR2_PACKAGE_${brPackage}=y`);
        });
    }
    outputLines.push('');

    // --- System Configuration ---
    if (config.network?.hostname) {
        outputLines.push(`BR2_TARGET_GENERIC_HOSTNAME="${config.network.hostname}"`);
    }
    // Network interface config (DHCP/Static) often requires /etc/network/interfaces
    // This script focuses on .config, overlays would be a separate step/feature.
    const dhcpInterface = config.network?.interfaces?.find(iface => iface.type === 'dhcp');
    if (dhcpInterface?.name) {
         outputLines.push(`BR2_SYSTEM_DHCP="${dhcpInterface.name}"`);
    }

    outputLines.push('');
    return outputLines.join('\n');
}

module.exports = { translateToBuildroot };